#!/usr/bin/env node
// Epic #202/#315/#317: animation_complete must be generated by canonical
// simulation steps, not by Pixi's shared render ticker / browser RAF.
import assert from 'node:assert/strict';
import { mkdirSync, writeFileSync } from 'node:fs';
import { chromium, webkit } from 'playwright';

const arg = (key, fallback) => {
  const i = process.argv.indexOf('--' + key);
  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
};
const base = arg('base', 'http://localhost:18099').replace(/\/$/, '');
const browserName = arg('browser', 'chromium');
const shots = arg('shots', '/tmp/runtime-animation-clock');
const browser = await (browserName === 'webkit' ? webkit : chromium).launch({ headless: true });
mkdirSync(shots, { recursive: true });
const results = [];
try {
  for (const profile of [
    { name: 'iphone-portrait', width: 390, height: 844 },
    { name: 'ipad-portrait', width: 820, height: 1180 },
  ]) {
    const page = await browser.newPage({
      viewport: { width: profile.width, height: profile.height }, hasTouch: true,
    });
    const errors = [];
    page.on('pageerror', e => errors.push(String(e)));
    try {
      await page.route('**/v1/games/*/package', async route => {
        const upstream = await route.fetch();
        assert.equal(upstream.status(), 200);
        const pkg = await upstream.json();
        assert.equal(pkg.gameId, 'escape-from-injection');
        const entity = pkg.ir.scenes[0].entities.find(e => e.id === 'player');
        assert.ok(entity, 'real Escape Game IR must have a player');
        entity.render = {
          ...entity.render,
          // Two-frame one-shot at six frames/second: exactly twenty 60Hz
          // ticks regardless of display pacing or paused compositor.
          animation: { frames: ['blob', 'chaser'], fps: 6, loop: false, autoplay: true },
        };
        pkg.ir.rules.push({
          id: 'synthetic-animation-tick-signal',
          when: { event: 'animation_complete', source: 'player' },
          actions: [{ type: 'add_variable', variable: 'animation_test_marker', value: 1 }],
        });
        await route.fulfill({ response: upstream, json: pkg });
      });
      await page.goto(base + '/player?game=escape-from-injection&presentation=play&probe=1&capture=1&seed=271828',
        { timeout: 30000 });
      await page.waitForFunction(() => window.__dqTest?.snapshot?.()?.capturePaused === true,
        null, { timeout: 30000 });
      const snapshot = () => page.evaluate(() => window.__dqTest.snapshot());
      const initial = await snapshot();
      assert.equal(initial.simStep, 0);
      assert.equal(initial.animations.find(a => a.id === 'player')?.frame, 0);
      assert.equal(initial.variables.animation_test_marker ?? 0, 0);
      // The page's browser render loop is still alive while the semantic
      // ticker is frozen in capture mode. No animation or rule may advance.
      await page.waitForTimeout(450);
      const paused = await snapshot();
      assert.equal(paused.simStep, 0);
      assert.equal(paused.animations.find(a => a.id === 'player')?.frame, 0);
      assert.equal(paused.variables.animation_test_marker ?? 0, 0);
      await page.evaluate(() => window.__dqBeginPlay?.());
      for (const [step, expectedMarker] of [[10, 0], [19, 0], [22, 1], [40, 1]]) {
        assert.equal(await page.evaluate(t => window.__dqTest.advanceToStep(t), step), true);
        await page.waitForFunction(t => window.__dqTest?.snapshot?.()?.simStep === t
          && window.__dqTest?.snapshot?.()?.capturePaused === true,
        step, { timeout: 30000 });
        const s = await snapshot();
        assert.equal(s.variables.animation_test_marker ?? 0, expectedMarker,
          'animation callback must fire once at deterministic virtual tick');
        assert.equal(s.ended, false, 'animation completion must not fabricate terminal win');
        assert.equal(s.failed, false, 'animation test must not produce runtime error');
      }
      const ended = await snapshot();
      assert.equal(ended.animations.find(a => a.id === 'player')?.playing, false);
      assert.deepEqual(errors, []);
      const screenshot = shots + '/' + browserName + '-' + profile.name + '.png';
      await page.screenshot({ path: screenshot });
      results.push({ browser: browserName, profile: profile.name, passed: true,
        firstSignalStep: 22, signalCount: 1, screenshot });
    } finally { await page.close(); }
  }
} finally { await browser.close(); }
writeFileSync(shots + '/report.json', JSON.stringify({
  browser: browserName, passed: results.length === 2, results,
}, null, 2));
console.log(JSON.stringify({ browser: browserName, passed: true, cases: results.length }));
